    "npc": "laca",
    "chapter": 5,
    "lines": [
     {
      "speaker": "laca",
      "text": "I brought two drinks and the last of those awful candies we used to love. The sunset is free."
     },
     {
      "speaker": "Protagonist",
      "text": "This looks familiar."
     },
     {
      "speaker": "laca",
      "text": "Same spot we used to watch the boats after swimming. Only now we can actually stay until dark."
     },
     {
      "speaker": "Protagonist",
      "text": "You went to a lot of trouble."
     },
     {
      "speaker": "laca",
      "text": "Nah. I wanted to. Also, I remembered your favorite drink, so I expect some admiration."
     },
     {
      "speaker": "laca",
      "text": "You know what was nice about having you back? I didn't have to explain myself. Not even the strange parts."
     },
     {
      "speaker": "Protagonist",
      "text": "You've always been my best friend."
     },
     {
      "speaker": "laca",
      "text": "And you mine. That's not changing. I needed to say that first."
     },
     {
      "speaker": "laca",
      "text": "I've been trying to figure out whether these feelings are just me getting nostalgic. They're not."
     },
     {
      "speaker": "laca",
      "text": "I'm still the girl who'll challenge you to a stupid rematch tomorrow. But I'd really like to know if we can be something more."
     },
     {
      "speaker": "Protagonist",
      "text": "Then let's be honest with each other."
     },
     {
      "speaker": "laca",
      "text": "Okay. No bets this time. Tell me what you want."
     }
    ],
    "choices": [
     {
      "label": "Ask Laca to be your girlfriend",
      "reply": "Yes. Absolutely yes. And for the record, I'm still going to steal your fries. Girlfriend privileges.",
      "kind": "commit",
      "flag": "romance",
      "delta": {
       "affection": 3,
       "trust": 2,
       "respect": 0,
       "attraction": 3
      }
     },
     {
      "label": "Choose to stay her closest friend",
      "reply": "Then that's us. Best friends, still unstoppable. Thanks for being honest with me.",
      "kind": "friend",
      "flag": "friendship",
      "delta": {
       "affection": 2,
       "trust": 2,
       "respect": 1,
       "attraction": 0
      }
     },
     {
      "label": "Say you cherish her but aren't ready for romance",
      "reply": "I can respect that. You don't owe me a love story, che. We've still got tomorrow.",
      "kind": "honest",
      "flag": "laca_ending_open",
      "delta": {
       "affection": 1,
       "trust": 2,
       "respect": 1,
       "attraction": 0
      }
     }
    ],
    "openingByFlag": {
     "laca_honest_friend": "You told me our friendship matters. I brought you back to the place where it really started.",
     "laca_honest_space": "I took the time you gave me. Turns out I know exactly what I want to ask you.",
     "laca_honest_mutual": "You said your feelings were changing too. I've been thinking about that all week. Come sit by me."
    }
